<script lang="ts">
	import { getContext, onMount, type Snippet } from "svelte";
	import type { LutraForm } from "./types.js";
	import { fieldChange, fieldKeydown, ignoreKeys } from "./client.svelte.js";
	import { getFromObjWithStringPath } from "./form.js";
	import { ZodType } from "zod";
	import FieldContent from "./FieldContent.svelte";

    /**
     * @description
     * A styled `<select>` element with a custom dropdown arrow, integrated with the
     * Lutra form system for validation and error display. Accepts options via props
     * or as `<option>` children via a snippet.
     *
     * @example
     * <Select name="country" label="Country" options={['US', 'UK', 'DE']} />
     * <Select name="role" label="Role" options={[
     *   { value: 'admin', label: 'Administrator' },
     *   { value: 'user', label: 'User' },
     * ]} />
     */
    let {
        autofocus,
        children,
        disabled,
        help,
        id = $bindable(crypto.randomUUID()),
        label,
        labelTip,
        name,
        onblur,
        onchange,
        onclick,
        onfocus,
        onkeydown,
        onkeyup,
        onkeypress,
        options,
        placeholder,
        required,
        results,
        shape = 'default',
        scale = 'md',
        tabindex,
        value = $bindable(),
    }: {
        /** Whether the input should be autofocused. */
        autofocus?: boolean;
        /** Options for the select element rendered as a snippet. */
        children?: Snippet;
        /** Whether the select should be disabled. */
        disabled?: boolean;
        /** Help text to display below the select. */
        help?: string | Snippet;
        /** A random id is generated if not provided. */
        id?: string;
        /** The label for the select. */
        label?: string | Snippet
        /** Context tooltip for the label. Renders with a questionmark using ContextTip. */
        labelTip?: string | Snippet;
        /** The name of the select element. */
        name: string;
        /** The onblur event handler */
        onblur?: (e: FocusEvent) => void;
        /** Onchange event handler */
        onchange?: (e: Event) => void;
        /** Onclick event handler */
        onclick?: (e: MouseEvent) => void;
        /** Onfocus event handler */
        onfocus?: (e: FocusEvent) => void;
        /** Keyup event handler */
        onkeyup?: (e: KeyboardEvent) => void;
        /** Keydown event handler */
        onkeydown?: (e: KeyboardEvent) => void;
        /** Keypress event handler */
        onkeypress?: (e: KeyboardEvent) => void;
        /** The options for the select element. */
        options?: string[] | { value: string; label: string }[];
        /** Placeholder text to display when the input is empty. */
        placeholder?: string;
        /** Suffix content, to display after the input. */
        suffix?: string | Snippet;
        /** Prefix content, to display before the input. */
        prefix?: string | Snippet;
        /** Whether the input should be required. */
        required?: boolean;
        /** The maximum number of items that should be displayed in the drop-down list of previous search queries. Safari only. */
        results?: number;
        /** The shape of the input element. */
        shape?: 'default' | 'rounded' | 'pill' | 'circle';
        /** Size variant controlling font-size. Em-based tokens cascade automatically. */
        scale?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
        /** Source URL for the image type. */
        src?: string;
        /** An integer attribute indicating if the element can take input focus (is focusable), if it should participate to sequential keyboard navigation. */
        tabindex?: number;
        /** The value of the input element. */
        value?: string | number | boolean | null;
    } = $props();

    let el: HTMLSelectElement | undefined = $state();

    // Set defaults from form context
    const form = getContext<LutraForm<any>>('form');
    const field = $derived(form?.fields[name]);
    const issue = $derived(form?.issues?.find((issue) => issue.name === name));
    const validator = getContext<Record<string, ZodType>>('form.validators')?.[name];
    const data = form?.data;
    const originalData = form?.originalData;
    if(!value) value = form ? (getFromObjWithStringPath(Object.assign(originalData ?? {}, data ?? {}), name) as string) || form?.fields?.[name]?.defaultValue as string : '';

    onMount(() => {
        if(value) fieldChange(form, name, () => el)({} as any);
    });

</script>

<FieldContent
    {id}
    {label}
    {labelTip}
    {help}
    {field}
    {issue}
    {required}
    {scale}
    contained
>
    <div class="SelectContainer">
        <select
            bind:this={el}
            {autofocus}
            {disabled}
            {id}
            {name}
            {onblur}
            {onclick}
            onchange={fieldChange(form, name, () => el, validator, onchange)}
            {onfocus}
            onkeydown={fieldKeydown(form, name, () => el, validator, onkeydown)}
            {onkeyup}
            {onkeypress}
            {placeholder}
            required={required || field?.required}
            {results}
            {tabindex}
            bind:value={value}
        >
            {#if children}
                {@render children()}
            {:else if options}
                {#each options as option}
                    {#if typeof option === 'string'}
                        <option value={option}>{option}</option>
                    {:else}
                        <option value={option.value}>{option.label}</option>
                    {/if}
                {/each}
            {/if}
        </select>
        <div class="Arrow">
            <svg width="12px" height="8px" viewBox="0 0 12 8" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
                <g transform="matrix(1,0,0,1,0,0.746639)">
                    <path d="M6,4.248L11.493,0L12,0.507L6,6.507L0,0.507L0.507,0L6,4.248Z" fill="currentColor" stroke="currentColor"/>
                </g>
            </svg>
        </div>
    </div>
</FieldContent>

<style>
    .SelectContainer {
        display: grid;
        grid-template-columns: 1fr;
        grid-template-areas: "select";
        align-items: center;
        width: 100%;
    }
    select {
        padding-inline-end: 2.5em;
        width: 100%;
        appearance: none;
        border: none;
        border-radius: 0;
        grid-area: select;
        background: none;
    }
    .Arrow {
        grid-area: select;
        pointer-events: none;
        display: flex;
        align-items: center;
        justify-content: end;
        padding-inline-end: var(--field-padding-inline);
    }
    svg {
        display: block;
        color: var(--field-color);
    }
    select:focus-visible {
        outline: none;
    }
</style>
